CREATE TABLE IF NOT EXISTS avatars (id text PRIMARY KEY, name text NOT NULL, engine text NOT NULL, status text NOT NULL DEFAULT 'CREATED', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS voices (id text PRIMARY KEY, name text NOT NULL, provider text NOT NULL, provider_voice_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY, name text NOT NULL, description text NOT NULL, price numeric(14,2) NOT NULL CHECK(price >= 0), currency text NOT NULL, stock integer NOT NULL CHECK(stock >= 0), sizes text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_bases (id text PRIMARY KEY, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_documents (id text PRIMARY KEY, knowledge_base_id text NOT NULL REFERENCES knowledge_bases(id), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS live_rooms (id text PRIMARY KEY, name text NOT NULL, avatar_id text NOT NULL REFERENCES avatars(id), voice_id text NOT NULL REFERENCES voices(id), knowledge_base_id text REFERENCES knowledge_bases(id), system_prompt text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS live_sessions (id text PRIMARY KEY, room_id text NOT NULL REFERENCES live_rooms(id), status text NOT NULL DEFAULT 'CREATED', runtime_operation_id text, failure_code text, failure_message text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, ended_at timestamptz);
CREATE TABLE IF NOT EXISTS utterances (id text PRIMARY KEY, session_id text NOT NULL REFERENCES live_sessions(id), source text NOT NULL, text text NOT NULL, priority integer NOT NULL, interrupt_policy text NOT NULL, status text NOT NULL DEFAULT 'QUEUED', trace_id text NOT NULL, failure_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, kind text NOT NULL, resource_id text NOT NULL, status text NOT NULL DEFAULT 'PENDING', failure_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS runtime_events (event_id text PRIMARY KEY, session_id text NOT NULL REFERENCES live_sessions(id), event_type text NOT NULL, utterance_id text, trace_id text NOT NULL, occurred_at timestamptz NOT NULL, envelope jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS runtime_events_session_created_idx ON runtime_events(session_id, created_at DESC);
CREATE TABLE IF NOT EXISTS idempotency_keys (key text NOT NULL, route text NOT NULL, request_hash text NOT NULL, response_status integer NOT NULL, response_body jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (key, route));
